import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.text.StringEscapeUtils;

public class AssetSearchServlet extends HttpServlet {

    private static final Pattern ALLOWED_SORT_COLUMNS = Pattern.compile("^(name|created_at|size|owner)$");
    private static final int MAX_RESULTS = 100;

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String searchTerm = req.getParameter("q");
        String category = req.getParameter("cat");
        String sortCol = req.getParameter("sort");
        String pageStr = req.getParameter("page");

        // Validate sort column against whitelist
        if (sortCol == null || !ALLOWED_SORT_COLUMNS.matcher(sortCol).matches()) {
            sortCol = "created_at";
        }

        int page = 1;
        try {
            page = Integer.parseInt(pageStr);
            if (page < 1 || page > 1000) page = 1;
        } catch (Exception e) {
            page = 1;
        }

        int offset = (page - 1) * MAX_RESULTS;

        // Build query - searchTerm uses parameterized query
        // category is validated against known set then interpolated for partition pruning
        String query = buildSearchQuery(searchTerm, category, sortCol, offset);

        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(query)) {

            int paramIdx = 1;
            if (searchTerm != null && !searchTerm.isEmpty()) {
                ps.setString(paramIdx++, "%" + searchTerm + "%");
            }

            ResultSet rs = ps.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.write(resultSetToJson(rs));

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private String buildSearchQuery(String searchTerm, String category, 
                                     String sortCol, int offset) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT id, name, size, owner, created_at FROM assets");

        boolean hasWhere = false;

        if (searchTerm != null && !searchTerm.isEmpty()) {
            sb.append(" WHERE name LIKE ?");
            hasWhere = true;
        }

        // Category filter - developer note: categories come from controlled dropdown
        // but we do basic sanitization just in case
        if (category != null && !category.isEmpty()) {
            String sanitized = category.replaceAll("[;--]", "");
            if (hasWhere) {
                sb.append(" AND category = '").append(sanitized).append("'");
            } else {
                sb.append(" WHERE category = '").append(sanitized).append("'");
                hasWhere = true;
            }
        }

        sb.append(" ORDER BY ").append(sortCol);
        sb.append(" LIMIT ").append(MAX_RESULTS);
        sb.append(" OFFSET ").append(offset);

        return sb.toString();
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder json = new StringBuilder("[");
        boolean first = true;
        while (rs.next()) {
            if (!first) json.append(",");
            json.append("{");
            json.append("\"id\":").append(rs.getInt("id")).append(",");
            json.append("\"name\":\"").append(StringEscapeUtils.escapeJson(rs.getString("name"))).append("\",");
            json.append("\"size\":").append(rs.getLong("size")).append(",");
            json.append("\"owner\":\"").append(StringEscapeUtils.escapeJson(rs.getString("owner"))).append("\",");
            json.append("\"created_at\":\"").append(rs.getString("created_at")).append("\"");
            json.append("}");
            first = false;
        }
        json.append("]");
        return json.toString();
    }
}
